                    content += f"- {finding}\n"
                elif isinstance(finding, dict):
                    content += f"- {finding.get('text', str(finding))}\n"
                else:
                    content += f"- {str(finding)}\n"
        elif isinstance(key_findings, str):
            content += f"- {key_findings}\n"

